package org.localsend.wear

import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import java.security.KeyPairGenerator
import java.security.KeyStore
import java.security.MessageDigest
import java.security.cert.X509Certificate as Cert
import java.util.Date
import javax.net.ssl.KeyManager
import javax.net.ssl.KeyManagerFactory
import javax.security.auth.x500.X500Principal

/**
 * The device identity: an RSA-2048 key in the Android Keystore with a self-signed certificate
 * (generated by the keystore itself, so no crypto library is needed).
 *
 * LocalSend peers identify each other by the SHA-256 of the certificate DER (uppercase hex),
 * and HTTPS peers *require* a client certificate, so sending to them needs this.
 */
class Identity private constructor(private val keyStore: KeyStore) {

    val certificate: Cert = keyStore.getCertificate(ALIAS) as Cert

    val fingerprint: String =
        MessageDigest.getInstance("SHA-256").digest(certificate.encoded)
            .joinToString("") { "%02X".format(it) }

    fun keyManagers(): Array<KeyManager> {
        val factory = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm())
        factory.init(keyStore, null)
        return factory.keyManagers
    }

    companion object {
        private const val ALIAS = "localsend_identity"

        fun loadOrCreate(): Identity {
            val ks = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
            if (!ks.containsAlias(ALIAS)) {
                val spec = KeyGenParameterSpec.Builder(ALIAS, KeyProperties.PURPOSE_SIGN or KeyProperties.PURPOSE_VERIFY)
                    .setKeySize(2048)
                    .setDigests(KeyProperties.DIGEST_SHA256, KeyProperties.DIGEST_SHA512)
                    .setSignaturePaddings(KeyProperties.SIGNATURE_PADDING_RSA_PKCS1, KeyProperties.SIGNATURE_PADDING_RSA_PSS)
                    .setCertificateSubject(X500Principal("CN=LocalSend User"))
                    .setCertificateNotBefore(Date(0))
                    .setCertificateNotAfter(Date(4_102_444_800_000L)) // year 2100
                    .build()
                KeyPairGenerator.getInstance(KeyProperties.KEY_ALGORITHM_RSA, "AndroidKeyStore")
                    .apply { initialize(spec) }
                    .generateKeyPair()
            }
            return Identity(ks)
        }
    }
}
